input.command:
cd /home/claude && cat > allyn_report.js << 'JSEOF'
const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
        AlignmentType, HeadingLevel, LevelFormat, BorderStyle, WidthType,
        ShadingType, VerticalAlign, PageBreak } = require('docx');
const fs = require('fs');

const border = { style: BorderStyle.SINGLE, size: 1, color: "CCCCCC" };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorders = {
  top: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  bottom: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  left: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  right: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
};

const ACCENT = "7B6B8D"; // soft plum
const ACCENT_LIGHT = "F0ECF5";
const ACCENT_DARK = "5A4F6A";
const GREEN = "2E7D52";
const GREEN_LIGHT = "EBF5EF";
const RED = "C0392B";
const RED_LIGHT = "FDECEA";
const GOLD = "B8860B";
const GOLD_LIGHT = "FEF9E7";

function h(text, level = HeadingLevel.HEADING_1, color = "1a1a2e") {
  return new Paragraph({
    heading: level,
    spacing: { before: 300, after: 120 },
    children: [new TextRun({ text, bold: true, color, font: "Arial",
      size: level === HeadingLevel.HEADING_1 ? 32 : level === HeadingLevel.HEADING_2 ? 26 : 22 })]
  });
}

function p(text, opts = {}) {
  return new Paragraph({
    spacing: { before: 80, after: 100 },
    children: [new TextRun({ text, font: "Arial", size: 22, ...opts })]
  });
}

function mixed(...runs) {
  return new Paragraph({
    spacing: { before: 80, after: 100 },
    children: runs.map(r => new TextRun({ font: "Arial", size: 22, ...r }))
  });
}

function bullet(text, ref = "bullets", bold = false) {
  return new Paragraph({
    numbering: { reference: ref, level: 0 },
    spacing: { before: 60, after: 60 },
    children: [new TextRun({ text, font: "Arial", size: 22, bold })]
  });
}

function subBullet(text) {
  return new Paragraph({
    numbering: { reference: "subbullets", level: 0 },
    spacing: { before: 40, after: 40 },
    children: [new TextRun({ text, font: "Arial", size: 20 })]
  });
}

function spacer() {
  return new Paragraph({ children: [new TextRun("")], spacing: { before: 60, after: 60 } });
}

function divider(color = ACCENT) {
  return new Paragraph({
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color, space: 1 } },
    spacing: { before: 120, after: 120 },
    children: [new TextRun("")]
  });
}

function tagBox(text, bg, textColor = "FFFFFF") {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    borders: { top: { style: BorderStyle.NONE }, bottom: { style: BorderStyle.NONE },
                left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE } },
    rows: [
      new TableRow({
        children: [
          new TableCell({
            width: { size: 9360, type: WidthType.DXA },
            shading: { fill: bg, type: ShadingType.CLEAR },
            margins: { top: 120, bottom: 120, left: 180, right: 180 },
            borders: noBorders,
            children: [new Paragraph({
              alignment: AlignmentType.LEFT,
              children: [new TextRun({ text, font: "Arial", size: 22, bold: true, color: textColor })]
            })]
          })
        ]
      })
    ]
  });
}

function twoCol(label, value, labelBg = ACCENT_LIGHT, labelColor = ACCENT_DARK) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [2800, 6560],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            width: { size: 2800, type: WidthType.DXA },
            shading: { fill: labelBg, type: ShadingType.CLEAR },
            margins: { top: 80, bottom: 80, left: 120, right: 120 },
            borders,
            children: [new Paragraph({
              children: [new TextRun({ text: label, font: "Arial", size: 22, bold: true, color: labelColor })]
            })]
          }),
          new TableCell({
            width: { size: 6560, type: WidthType.DXA },
            margins: { top: 80, bottom: 80, left: 120, right: 120 },
            borders,
            children: [new Paragraph({
              children: [new TextRun({ text: value, font: "Arial", size: 22 })]
            })]
          })
        ]
      })
    ]
  });
}

const doc = new Document({
  numbering: {
    config: [
      { reference: "bullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "•",
          alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] },
      { reference: "subbullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "◦",
          alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 1080, hanging: 360 } } } }] },
      { reference: "numbers", levels: [{ level: 0, format: LevelFormat.DECIMAL, text: "%1.",
          alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] },
    ]
  },
  styles: {
    default: { document: { run: { font: "Arial", size: 22 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 32, bold: true, font: "Arial", color: "1a1a2e" },
        paragraph: { spacing: { before: 300, after: 160 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 26, bold: true, font: "Arial", color: ACCENT_DARK },
        paragraph: { spacing: { before: 240, after: 120 }, outlineLevel: 1 } },
      { id: "Heading3", name: "Heading 3", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 22, bold: true, font: "Arial", color: "333333" },
        paragraph: { spacing: { before: 180, after: 80 }, outlineLevel: 2 } },
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1080, right: 1440, bottom: 1080, left: 1440 }
      }
    },
    children: [
      // ─── HEADER BLOCK ───
      tagBox("SECRET SHOPPER RECONNAISSANCE REPORT", ACCENT_DARK),
      spacer(),
      new Table({
        width: { size: 9360, type: WidthType.DXA },
        columnWidths: [9360],
        rows: [new TableRow({ children: [new TableCell({
          width: { size: 9360, type: WidthType.DXA },
          shading: { fill: ACCENT_LIGHT, type: ShadingType.CLEAR },
          margins: { top: 160, bottom: 160, left: 240, right: 240 },
          borders: noBorders,
          children: [
            new Paragraph({ alignment: AlignmentType.CENTER,
              children: [new TextRun({ text: "Allyn Aesthetics — Mount Juliet, TN", font: "Arial", size: 36, bold: true, color: ACCENT_DARK })] }),
            spacer(),
            new Paragraph({ alignment: AlignmentType.CENTER,
              children: [new TextRun({ text: "Prepared by: Bethany Gifford, The Luxora Collective", font: "Arial", size: 20, color: "555555" })] }),
            new Paragraph({ alignment: AlignmentType.CENTER,
              children: [new TextRun({ text: "Classification: Confidential — For Ownership/Management Review Only", font: "Arial", size: 20, color: "555555" })] }),
          ]
        })]})]
      }),
      spacer(),
      spacer(),

      // ─── EXECUTIVE SUMMARY ───
      h("Executive Summary"),
      divider(),
      p("Allyn Aesthetics has built something truly special in Mount Juliet. The physical space is stunning — warm, calming, and luxurious in a way that immediately signals quality to every client who walks through the door. Your esthetician team is knowledgeable, personable, and delivers an exceptional treatment experience. Thoughtful touches like the online booking preference for quiet vs. chatty treatments show real attentiveness to client comfort. The full-service salon concept is a genuine differentiator, and your product selection is impressive."),
      spacer(),
      p("That said, the foundation you've built deserves a business model that fully captures its value. Currently, significant revenue is being left on the table through gaps in front desk protocol, an underutilized membership program, the absence of service packages, and missed upsell opportunities at every touchpoint. The good news: every single gap identified is completely solvable — and in many cases, can be addressed quickly with the right systems and training."),
      spacer(),
      p("This report identifies the key areas for improvement, celebrates your genuine strengths, and outlines a strategic roadmap to convert one-time visitors into lifelong, high-value clients."),
      spacer(),

      // ─── MARKET PRESENCE ───
      h("Market Presence Assessment"),
      divider(),
      p("Allyn Aesthetics occupies a unique position in Mount Juliet — a market with growing affluence and aesthetic awareness, yet situated at a meaningful geographic distance from the dense competitive corridors of Nashville and Williamson County. This distance is a double-edged sword: less local competition, but also reduced organic foot traffic and fewer spontaneous discovery opportunities."),
      spacer(),
      tagBox("RECOMMENDATION PRIORITY: HIGH — Proactive community partnership strategy and hyperlocal digital presence are essential to bridge the geographic gap.", GOLD, "1a1a0a"),
      spacer(),
      p("The strategic opportunity here is to position Allyn Aesthetics as the premier destination spa for Mount Juliet and surrounding communities, so residents stop making the drive into Nashville when everything they need is right here. Achieving that requires intentional visibility — both online and through community relationships."),
      spacer(),

      // ─── STAFF PERFORMANCE ───
      h("Staff Performance Evaluation"),
      divider(),

      h("Esthetician — Clinical Services", HeadingLevel.HEADING_2),
      tagBox("OVERALL RATING: EXCEPTIONAL ★★★★★", GREEN, "FFFFFF"),
      spacer(),
      p("Your esthetician was a standout. She demonstrated deep knowledge of the services, was warm and engaging, and — critically — she actually listened to who I was as a client. When she saw I had selected the 'chatty' preference during booking, she seamlessly blended treatment education with genuine conversation. That kind of responsiveness is rare and speaks to exceptional emotional intelligence and client-centered care."),
      spacer(),
      bullet("Thorough knowledge of treatments and ability to explain them clearly"),
      bullet("Genuinely warm, personable chair-side manner"),
      bullet("Responsive to client preferences — pivoted naturally to match the chatty booking selection"),
      bullet("Created a comfortable, trust-building environment throughout the service"),
      spacer(),
      p("She is a tremendous asset and should be highlighted in marketing materials, social content, and client-facing communication. Her approach to client interaction is the model the entire team should emulate."),
      spacer(),

      h("Front Desk — Client Experience", HeadingLevel.HEADING_2),
      tagBox("OVERALL RATING: NEEDS DEVELOPMENT ⚠", GOLD, "1a1a0a"),
      spacer(),
      p("Phone and in-person interactions at the front desk represent the very first impression Allyn Aesthetics makes on a potential client — and currently, those interactions are falling short of the standard the rest of the business sets. Several specific gaps were observed:"),
      spacer(),

      h("Phone Interaction Observations:", HeadingLevel.HEADING_3),
      bullet("Did not introduce herself by name when answering the call — a basic but critical professionalism standard"),
      bullet("Demonstrated limited knowledge of Ultherapy, including pricing — this is a premium, high-ticket service and front desk staff should be able to speak to it confidently"),
      bullet("Did not ask discovery questions — such as what concern the caller was trying to address — to open the door to a fuller consultation or alternate solutions"),
      bullet("While she did offer a consultation, she did not explore the caller's underlying goal or mention complementary services that might meet their needs"),
      spacer(),

      h("In-Person Interaction Observations:", HeadingLevel.HEADING_3),
      bullet("Did not introduce herself to clients upon arrival — neither to me nor to other clients observed during the visit"),
      bullet("Did not offer a tour of the facility, treatment rooms, or technology"),
      bullet("Did not proactively mention the full range of services or current offerings"),
      bullet("Did not mention the membership program — despite membership plaques being visible in the space"),
      bullet("Did not offer any beverage upon arrival or during wait time"),
      bullet("Placed me in the waiting area without checking in to see if I needed anything"),
      spacer(),
      p("These are not reflections of character — they are reflections of a lack of standardized protocol. With the right training framework and scripting, these interactions can be transformed quickly."),
      spacer(),

      // ─── OPERATIONAL OBSERVATIONS ───
      h("Operational Observations"),
      divider(),

      h("Client Experience Protocol — NEEDS IMPROVEMENT", HeadingLevel.HEADING_2),
      tagBox("Priority: IMMEDIATE", RED, "FFFFFF"),
      spacer(),

      h("What Was Missing:", HeadingLevel.HEADING_3),
      spacer(),

      twoCol("No Beverage Service", "Clients were not offered water, tea, coffee, or any refreshment upon arrival or during wait time. This is a standard luxury touchpoint that significantly shapes the perceived level of care — especially in a beautiful, high-end space like yours."),
      spacer(),
      twoCol("No Facility Tour", "New clients were not shown the treatment areas, laser suite, salon, or technology offerings. A brief tour builds excitement, creates organic upsell opportunities by letting clients see the equipment, and establishes trust through transparency."),
      spacer(),
      twoCol("No Staff Introduction", "Staff did not introduce themselves by name, role, or specialty — either on the phone or in person. Clients should immediately know who is helping them and what expertise that person brings."),
      spacer(),
      twoCol("No Service Menu Communication", "There was minimal proactive communication about the full range of services. Staff should be weaving 2-3 relevant services or offerings into every single client interaction — especially for new visitors."),
      spacer(),
      twoCol("No Membership Mention", "The membership program was completely absent from conversation, despite visible plaques in the waiting area. This is one of your most powerful tools for client retention and recurring revenue — it should come up in virtually every client interaction."),
      spacer(),
      spacer(),

      h("Membership Program — SIGNIFICANT OPPORTUNITY", HeadingLevel.HEADING_2),
      tagBox("Priority: HIGH — Revenue Multiplier", ACCENT_DARK, "FFFFFF"),
      spacer(),
      p("The membership structure at Allyn Aesthetics has real potential but is currently underperforming as a revenue driver. Based on the visit, the program appears to exist in the background rather than at the forefront of the client experience. To become a competitive differentiator, the membership program needs both a structural refresh and a culture shift around how it's presented."),
      spacer(),
      h("Current State:", HeadingLevel.HEADING_3),
      bullet("Membership plaques are present but not discussed"),
      bullet("Staff are not introducing the program as part of any consultation or visit"),
      bullet("No sense of excitement or urgency around membership benefits"),
      spacer(),
      h("What a Revamped Membership Program Should Look Like:", HeadingLevel.HEADING_3),
      bullet("Clearly tiered structure (e.g., Glow, Radiance, Luxe) with distinct, compelling benefits at each level"),
      bullet("Monthly credit toward services, exclusive member pricing, and priority booking"),
      bullet("Members-only perks: first access to new treatments, referral bonuses, birthday credits"),
      bullet("Physical membership card or digital badge that makes members feel special"),
      bullet("Every staff member trained to mention membership as the smartest way to be a regular client"),
      bullet("Goal: Every new client should leave with the membership pitch — and at minimum, understand what it offers"),
      spacer(),

      h("Service Packages — NOT CURRENTLY OFFERED — IMMEDIATE OPPORTUNITY", HeadingLevel.HEADING_2),
      tagBox("Priority: HIGH — Significant Revenue Capture", RED, "FFFFFF"),
      spacer(),
      p("Currently, Allyn Aesthetics appears to be operating almost exclusively on a one-off treatment model. This is one of the single biggest missed opportunities in the business. Packages dramatically increase average client spend, improve retention, and make treatment planning a natural part of every visit."),
      spacer(),
      h("Suggested Package Concepts to Launch:", HeadingLevel.HEADING_3),
      bullet("Bridal Glow Package — Pre-wedding skin prep series (ideal for the Mount Juliet/Williamson County bridal market)"),
      bullet("Mommy Makeover Package — Post-pregnancy refresh combining body treatments, facials, and injectables"),
      bullet("Summer Body Ready Package — Seasonal bundle targeting body contouring, hair removal, and skin treatments"),
      bullet("New Client Starter Package — An accessible entry point that introduces clients to multiple service categories"),
      bullet("Anti-Aging Essentials Package — Curated series combining laser, injectables, and skincare for clients focused on prevention and reversal"),
      spacer(),
      p("Packages should be tiered (Good/Better/Best pricing) and presented during every consultation. They are also perfect for gift card promotions, seasonal campaigns, and bridal show marketing."),
      spacer(),

      // ─── REVENUE OPPORTUNITIES ───
      h("Strategic Revenue Opportunities"),
      divider(),

      h("Treatment Plans for Every Client", HeadingLevel.HEADING_2),
      p("You already have a 'Build My Treatment Plan' feature online — this is a genuinely impressive and underutilized asset. The concept needs to move from an optional digital tool to a required in-clinic experience. Every new client should leave with a customized treatment plan. Every returning client should be asked about their progress and have their plan updated. This single shift can dramatically increase return visit frequency and average client spend."),
      spacer(),
      tagBox("ACTION ITEM: Train all providers to close every appointment by reviewing or building the client's treatment plan. No client should leave without a clear next step.", ACCENT_DARK, "FFFFFF"),
      spacer(),

      h("Laser Utilization — Maximize Equipment ROI", HeadingLevel.HEADING_2),
      p("Laser equipment represents a significant capital investment with high per-treatment revenue potential. Currently, it is unclear whether the laser suite is being booked to capacity. A strategic focus on laser education (for both staff and clients), targeted campaigns, and package bundling around laser services can dramatically improve equipment ROI. The goal should be to have lasers booked out daily — not opportunistically."),
      spacer(),

      h("Staff Upsell Culture — Every Visit Teaches Something New", HeadingLevel.HEADING_2),
      p("One of the highest-ROI changes you can make costs nothing: train every staff member to ensure that every client — new or returning — learns something new about Allyn Aesthetics at every single visit. Whether it's a new treatment, a membership benefit, a seasonal package, or an equipment capability, this practice builds awareness and creates organic upsell moments without feeling salesy."),
      spacer(),
      tagBox("Every client interaction is a marketing opportunity. Every staff member is a salesperson — whether or not they know it.", ACCENT, "FFFFFF"),
      spacer(),

      h("Geographic Partnership Strategy", HeadingLevel.HEADING_2),
      p("Given Allyn Aesthetics' location relative to Nashville and Williamson County, strategic community partnerships are not optional — they are essential. The goal is to create referral pipelines that bring new clients to your door without paid advertising spend."),
      spacer(),
      h("Priority Partnership Categories:", HeadingLevel.HEADING_3),
      bullet("Wedding vendors: photographers, dress boutiques, event planners, florists in the Mt. Juliet/Lebanon area"),
      bullet("Fitness studios and gyms: natural crossover with body contouring and skin clients"),
      bullet("Real estate agents: connecting with new homeowners moving into the area — a warm, high-value introduction"),
      bullet("OB-GYNs and primary care providers: referral relationships for hormone, wellness, and post-pregnancy services"),
      bullet("Hair salons and nail studios: complementary services, no competition"),
      bullet("Boutiques and lifestyle brands: co-branded promotions and pop-up events"),
      spacer(),

      // ─── STRENGTHS ───
      h("What Allyn Aesthetics Is Doing Exceptionally Well"),
      divider(),
      tagBox("These strengths are your competitive foundation — protect and amplify them.", GREEN, "FFFFFF"),
      spacer(),

      bullet("Beautiful, calming physical space — the environment immediately communicates luxury and professionalism", false),
      bullet("Welcoming, well-curated waiting area — clients feel comfortable from the moment they arrive", false),
      bullet("Extensive product selection — gives clients a reason to shop and adds retail revenue potential", false),
      bullet("Full-service salon integration — a true one-stop-shop concept that is a genuine differentiator in this market", false),
      bullet("Exceptional esthetician team — knowledgeable, warm, and client-focused in exactly the right way", false),
      bullet("Chatty/Quiet booking preference — a thoughtful, innovative touch that clients notice and remember", false),
      bullet("Online 'Build My Treatment Plan' feature — this is ahead of the curve; it just needs to be activated in-clinic as well", false),
      spacer(),

      // ─── ACTION PLAN ───
      h("Strategic Action Plan"),
      divider(),

      h("IMMEDIATE PRIORITIES — First 30 Days", HeadingLevel.HEADING_2),
      spacer(),

      new Paragraph({ numbering: { reference: "numbers", level: 0 }, spacing: { before: 100, after: 60 },
        children: [new TextRun({ text: "Implement a Standardized Client Welcome Protocol", font: "Arial", size: 22, bold: true })] }),
      subBullet("Script and train: phone greeting (name, role, warm welcome)"),
      subBullet("In-person: introduce by name and role within 30 seconds of client arrival"),
      subBullet("Beverage offer within 2 minutes: 'Can I get you water, coffee, or tea while you wait?'"),
      subBullet("Brief facility tour for every new client highlighting key treatment areas, salon, and laser suite"),
      subBullet("Every staff member mentions 2-3 services or the membership program during every visit"),
      spacer(),

      new Paragraph({ numbering: { reference: "numbers", level: 0 }, spacing: { before: 100, after: 60 },
        children: [new TextRun({ text: "Front Desk Service Knowledge Training", font: "Arial", size: 22, bold: true })] }),
      subBullet("Every front desk team member must be able to speak confidently to every service offered — especially premium offerings like Ultherapy, laser treatments, and memberships"),
      subBullet("Price ranges, ideal candidates, and what results to expect — all at their fingertips"),
      subBullet("Discovery question training: 'What's the main concern you're hoping to address?' opens the door to tailored recommendations"),
      spacer(),

      new Paragraph({ numbering: { reference: "numbers", level: 0 }, spacing: { before: 100, after: 60 },
        children: [new TextRun({ text: "Membership Program — Activate as a Sales Priority", font: "Arial", size: 22, bold: true })] }),
      subBullet("Every new client should receive a membership pitch before they leave — framed as the smartest way to achieve their goals"),
      subBullet("Create a simple one-page membership menu card for the waiting room and treatment rooms"),
      subBullet("Begin the process of revamping the membership tiers for a fresh 2025 rollout"),
      spacer(),

      h("SHORT-TERM INITIATIVES — 30 to 90 Days", HeadingLevel.HEADING_2),
      spacer(),

      new Paragraph({ numbering: { reference: "numbers", level: 0 }, spacing: { before: 100, after: 60 },
        children: [new TextRun({ text: "Launch Service Package Offerings", font: "Arial", size: 22, bold: true })] }),
      subBullet("Design 3-5 signature packages (Bridal, Mommy Makeover, Summer Body, Anti-Aging, New Client Intro)"),
      subBullet("Build Good/Better/Best pricing tiers for each"),
      subBullet("Train all staff to present packages as part of every consultation"),
      subBullet("Feature packages prominently on the website, social media, and in-clinic displays"),
      spacer(),

      new Paragraph({ numbering: { reference: "numbers", level: 0 }, spacing: { before: 100, after: 60 },
        children: [new TextRun({ text: "In-Clinic Treatment Plan Culture", font: "Arial", size: 22, bold: true })] }),
      subBullet("Bring the online 'Build My Treatment Plan' tool into the physical experience"),
      subBullet("Every new client completes a treatment plan before leaving — with a clear first next step booked"),
      subBullet("Every returning client has their plan reviewed and updated"),
      subBullet("Treatment plans become the framework for every upsell conversation"),
      spacer(),

      new Paragraph({ numbering: { reference: "numbers", level: 0 }, spacing: { before: 100, after: 60 },
        children: [new TextRun({ text: "Membership Program Revamp", font: "Arial", size: 22, bold: true })] }),
      subBullet("Audit current membership tiers and benefits against competitor offerings in the Nashville/Williamson County market"),
      subBullet("Redesign with fresh branding, compelling tier names, and clearly articulated value at each level"),
      subBullet("Build a referral component into the membership (members who refer friends earn credits)"),
      subBullet("Create a launch campaign around the revamp to re-engage existing members and attract new sign-ups"),
      spacer(),

      new Paragraph({ numbering: { reference: "numbers", level: 0 }, spacing: { before: 100, after: 60 },
        children: [new TextRun({ text: "Strategic Partnership Development", font: "Arial", size: 22, bold: true })] }),
      subBullet("Identify and approach 5-10 priority partners in the Mount Juliet/Lebanon corridor"),
      subBullet("Create a formal referral agreement with mutual promotion benefits"),
      subBullet("Host a VIP partner appreciation event at the spa to build relationships and generate buzz"),
      subBullet("Target wedding vendors first given the high-value bridal market opportunity"),
      spacer(),

      h("MEDIUM-TERM GROWTH — 90 to 180 Days", HeadingLevel.HEADING_2),
      spacer(),

      new Paragraph({ numbering: { reference: "numbers", level: 0 }, spacing: { before: 100, after: 60 },
        children: [new TextRun({ text: "Laser Revenue Maximization Campaign", font: "Arial", size: 22, bold: true })] }),
      subBullet("Audit current laser booking rates and identify capacity gaps"),
      subBullet("Create dedicated laser campaigns (seasonal, concern-based, package-driven) to fill open slots"),
      subBullet("Train all staff on laser services so they can speak to them with confidence in every interaction"),
      subBullet("Goal: laser suites booked to capacity daily"),
      spacer(),

      new Paragraph({ numbering: { reference: "numbers", level: 0 }, spacing: { before: 100, after: 60 },
        children: [new TextRun({ text: "Marketing Delegation & ROI Optimization", font: "Arial", size: 22, bold: true })] }),
      subBullet("Assess where owner time is currently spent on marketing vs. higher-value activities"),
      subBullet("Delegate social content creation, email marketing, and ad management to specialized partners"),
      subBullet("Implement tracking for every marketing channel to understand what is actually driving bookings"),
      subBullet("Shift from general awareness marketing to conversion-focused campaigns with measurable ROI"),
      spacer(),

      new Paragraph({ numbering: { reference: "numbers", level: 0 }, spacing: { before: 100, after: 60 },
        children: [new TextRun({ text: "Staff Development & Service Knowledge Elevation", font: "Arial", size: 22, bold: true })] }),
      subBullet("Monthly deep-dive training on one service category (staff should be able to explain every treatment to any client)"),
      subBullet("Commission structure or incentive program for successful upsells, rebookings, and membership sign-ups"),
      subBullet("Role-play training for difficult client conversations (hesitant clients, budget objections, etc.)"),
      subBullet("Recognition program for staff who excel in client experience and retention metrics"),
      spacer(),

      // ─── LUXORA PARTNERSHIP ───
      h("How The Luxora Collective's 90-Day Program Addresses These Gaps"),
      divider(),
      p("The challenges identified at Allyn Aesthetics are not unique — they are the exact patterns we see in nearly every independent med spa that has built genuine clinical excellence but hasn't yet built the business infrastructure to match. Our 90-Day Medspa Transformation Program is specifically designed to convert this exact scenario into explosive growth."),
      spacer(),
      h("What the 90-Day Program Delivers:", HeadingLevel.HEADING_3),
      bullet("Month 1: Deep operational audit, staff interviews, competitive positioning analysis, and custom strategic roadmap"),
      bullet("Month 1-2: Priority implementations — client welcome protocols, membership revamp, package launch, front desk training, and initial marketing campaigns"),
      bullet("Month 2-3: Scaling successful systems, treatment plan culture activation, partnership development, laser maximization strategy"),
      bullet("Ongoing: Monthly performance reviews, accountability check-ins, continuous optimization"),
      spacer(),
