const borders = { top: border, bottom: border, left: border, right: border };
const noBorders = {
  top: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  bottom: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  left: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  right: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
};

const ACCENT = "7B6B8D"; // soft plum
const ACCENT_LIGHT = "F0ECF5";
const ACCENT_DARK = "5A4F6A";
const GREEN = "2E7D52";
const GREEN_LIGHT = "EBF5EF";
const RED = "C0392B";
const RED_LIGHT = "FDECEA";
const GOLD = "B8860B";
const GOLD_LIGHT = "FEF9E7";

function h(text, level = HeadingLevel.HEADING_1, color = "1a1a2e") {
  return new Paragraph({
    heading: level,
    spacing: { before: 300, after: 120 },
    children: [new TextRun({ text, bold: true, color, font: "Arial",
      size: level === HeadingLevel.HEADING_1 ? 32 : level === HeadingLevel.HEADING_2 ? 26 : 22 })]
  });
}

function p(text, opts = {}) {
  return new Paragraph({
    spacing: { before: 80, after: 100 },
    children: [new TextRun({ text, font: "Arial", size: 22, ...opts })]
  });
}

function mixed(...runs) {
  return new Paragraph({
    spacing: { before: 80, after: 100 },
    children: runs.map(r => new TextRun({ font: "Arial", size: 22, ...r }))
  });
}

function bullet(text, ref = "bullets", bold = false) {
  return new Paragraph({
    numbering: { reference: ref, level: 0 },
    spacing: { before: 60, after: 60 },
    children: [new TextRun({ text, font: "Arial", size: 22, bold })]
  });
}

function subBullet(text) {
  return new Paragraph({
    numbering: { reference: "subbullets", level: 0 },
    spacing: { before: 40, after: 40 },
    children: [new TextRun({ text, font: "Arial", size: 20 })]
  });
}

function spacer() {
  return new Paragraph({ children: [new TextRun("")], spacing: { before: 60, after: 60 } });
}

function divider(color = ACCENT) {
  return new Paragraph({
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color, space: 1 } },
    spacing: { before: 120, after: 120 },
    children: [new TextRun("")]
