// ─── COLOR PALETTE ───────────────────────────────────────────
const PLUM       = "5A4F6A";
const PLUM_MID   = "7B6B8D";
const PLUM_LIGHT = "F0ECF5";
const GOLD       = "8B6914";
const GOLD_LIGHT = "FEF8E8";
const GREEN      = "2E6B46";
const GREEN_LIGHT= "EBF5EF";
const DARK       = "1A1A2E";
const MID        = "444444";
const LIGHT_GRAY = "F7F7F7";
const RULE_COLOR = "C8BEDB";

// ─── NUMBERING CONFIG ─────────────────────────────────────────
