  ]
};

// ─── HELPERS ─────────────────────────────────────────────────

function sp(before = 80, after = 80) {
  return { spacing: { before, after } };
}

function body(text, opts = {}) {
  return new Paragraph({
    ...sp(80, 100),
    children: [new TextRun({ text, font: "Arial", size: 22, color: MID, ...opts })]
  });
}

function bodyMixed(runs) {
  return new Paragraph({
    ...sp(80, 100),
    children: runs.map(r => new TextRun({ font: "Arial", size: 22, color: MID, ...r }))
  });
}

function gap(n = 1) {
  return Array.from({ length: n }, () =>
    new Paragraph({ children: [new TextRun("")], ...sp(40, 40) })
  );
}

function rule(color = RULE_COLOR) {
  return new Paragraph({
    border: { bottom: { style: BorderStyle.SINGLE, size: 3, color, space: 1 } },
    ...sp(0, 140),
    children: [new TextRun("")]
  });
}

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text, font: "Arial", size: 34, bold: true, color: DARK })]
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    children: [new TextRun({ text, font: "Arial", size: 26, bold: true, color: PLUM })]
  });
}

function h3(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_3,
    children: [new TextRun({ text, font: "Arial", size: 22, bold: true, color: DARK })]
  });
}

function bullet(text) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    ...sp(60, 60),
    children: [new TextRun({ text, font: "Arial", size: 22, color: MID })]
  });
}

function subBullet(text) {
  return new Paragraph({
    numbering: { reference: "sub", level: 0 },
    ...sp(40, 40),
    children: [new TextRun({ text, font: "Arial", size: 21, color: MID })]
  });
}

